#' Python Runtime Check
#'
#' 
#' @param data .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$runtime} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$runtime$asDF}
#'
#' \code{as.data.frame(results$runtime)}
#'
#' @export
pyruntime <- function(
    data,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pyruntime requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- pyruntimeOptions$new(
        showConsole = showConsole)

    analysis <- pyruntimeClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

